  bit reported [6729];
  task automatic cmp(int idx, string name, logic [1023:0] g, logic [1023:0] i, int w);
    logic [1023:0] mask;
    mask = (1024'h1 << w) - 1;
    checks++;
    if (!$isunknown(g & mask) && ((g & mask) !== (i & mask))) begin
      errors++;
      if (!reported[idx]) begin reported[idx] = 1; distinct_div++;
        if (distinct_div <= 40) $display("[MISMATCH %0t] %s g=%h i=%h", $time, name, g & mask, i & mask);
      end
    end
  endtask
